#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 100
int top = 0;
long stack[MAX_SIZE];
int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <expression>\n", argv[0]);
        return 1;
    }
    char *expression = argv[1];
    for (int i = 0; i < strlen(expression); i++) {
        char c = expression[i];
        if (c == '+') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            long b = stack[top - 1];
            long a = stack[top - 2];
            stack[top - 2] = a + b;
            top--;
        } else if (c == '-') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            long b = stack[top - 1];
            long a = stack[top - 2];
            stack[top - 2] = a - b;
            top--;
        } else if (c == '*') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            long b = stack[top - 1];
            long a = stack[top - 2];
            stack[top - 2] = a * b;
            top--;
        } else if (c == '/') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            long b = stack[top - 1];
            long a = stack[top - 2];
            if (b == 0) {
                printf("ERROR\n");
                return 1;
            }
            stack[top - 2] = a / b;
            top--;
        } else {
            char *end;
            long num = strtol(&c, &end, 10);
            if (*end != '\0') {
                printf("ERROR\n");
                return 1;
            }
            if (top >= MAX_SIZE) {
                printf("ERROR\n");
                return 1;
            }
            stack[top] = num;
            top++;
        }
    }
    if (top != 1) {
        printf("ERROR\n");
        return 1;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
